-- MariaDB's header order: OR REPLACE comes straight after CREATE, before
-- DEFINER, and AGGREGATE just before FUNCTION.
CREATE OR REPLACE DEFINER = CURRENT_USER FUNCTION f1(IN a INT)
RETURNS INT
    RETURN a;

CREATE OR REPLACE DEFINER = 'u'@'%' PROCEDURE p1()
    SELECT 1;

CREATE DEFINER = 'u'@'%' AGGREGATE FUNCTION IF NOT EXISTS f2(IN x INT)
RETURNS INT
BEGIN
    DECLARE total INT DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR NOT FOUND RETURN total;
    LOOP
        FETCH GROUP NEXT ROW;
        SET total = total + x;
    END LOOP;
END;

CREATE OR REPLACE DEFINER = CURRENT_USER EVENT e1
ON SCHEDULE EVERY 1 DAY
DO SELECT 1;

-- CURRENT_ROLE, with or without brackets, like CURRENT_USER.
CREATE DEFINER = CURRENT_ROLE PROCEDURE p2()
    SELECT 1;

CREATE DEFINER = CURRENT_ROLE() PROCEDURE p3()
    SELECT 1;
